{{
    config(
        materialized='incremental',
        unique_key='order_id',
        incremental_strategy='merge',
        on_schema_change='append_new_columns'
    )
}}

with orders as (
    select * from {{ ref('int_orders__enriched') }}
    {% if is_incremental() %}
    -- only the rows loaded after the last run (coalesce: the table may be empty)
    where loaded_at > (
        select coalesce(max(loaded_at), cast('1900-01-01' as timestamp)) from {{ this }}
    )
    {% endif %}
)

select
    order_id,
    customer_id,
    order_date,
    status,
    paid_amount as amount,
    loaded_at
from orders

{% snapshot orders_snapshot_legacy %}
{{
    config(
        target_schema='snapshots',
        unique_key='id',
        strategy='timestamp',
        updated_at='_loaded_at'
    )
}}
select * from {{ source('jaffle_shop', 'orders') }}
{% endsnapshot %}

{% test is_positive(model, column_name) %}
select *
from {{ model }}
where {{ column_name }} < 0
{% endtest %}

{% macro cents_to_dollars(column_name, scale=2) -%}
    cast({{ column_name }} / 100 as decimal(16, {{ scale }}))
{%- endmacro %}

{% macro print_row_counts(materializations=['table', 'incremental']) %}
    {% if execute %}
        {% for node in graph.nodes.values()
              | selectattr('resource_type', 'equalto', 'model')
              | sort(attribute='name') %}
            {% if node.config.materialized in materializations %}
                {% set relation = adapter.get_relation(
                    database=node.database,
                    schema=node.schema,
                    identifier=node.alias) %}
                {% if relation is none %}
                    {{ log(node.name ~ ': not built yet', info=true) }}
                {% else %}
                    {% set result = run_query('select count(*) from ' ~ relation) %}
                    {{ log(node.name ~ ': ' ~ result.columns[0].values()[0] ~ ' rows', info=true) }}
                {% endif %}
            {% endif %}
        {% endfor %}
    {% endif %}
{% endmacro %}

{% macro generate_schema_name(custom_schema_name, node) -%}
    {%- set default_schema = target.schema -%}
    {%- if target.name == 'prod' and custom_schema_name is not none -%}
        {{ custom_schema_name | trim }}
    {%- else -%}
        {{ default_schema }}
    {%- endif -%}
{%- endmacro %}

def model(dbt, session):
    dbt.config(materialized="table")          # table or incremental only

    customers = dbt.ref("dim_customers").df()  # .df(): DuckDB relation -> pandas

    def segment(row):
        if row["number_of_orders"] == 0:
            return "no orders"
        if row["number_of_orders"] >= 4 or row["lifetime_value"] >= 100:
            return "loyal"
        if row["number_of_orders"] >= 2:
            return "regular"
        return "new"

    customers["segment"] = customers.apply(segment, axis=1)
    return customers[["customer_id", "country", "number_of_orders", "lifetime_value", "segment"]]
